#!/usr/bin/env python3
"""Write the Phase81P official-method audit from pinned local checkouts."""
from __future__ import annotations
import datetime, hashlib, json, os, subprocess
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / "outputs/iclr27_phase81p/audit/literature_audit.json"

def head(repo: str) -> str:
    try: return subprocess.check_output(["git", "-C", str(ROOT / repo), "rev-parse", "HEAD"], text=True).strip()
    except Exception: return "not_checked_out"

def license_name(repo: str) -> str:
    p = ROOT / repo
    for name in ("LICENSE", "LICENSE.md", "LICENSE.txt"):
        if (p / name).is_file():
            text=(p/name).read_text(errors="ignore")[:1000].lower()
            if "apache" in text: return "Apache-2.0"
            if "mit license" in text or "permission is hereby granted" in text: return "MIT"
            return "present_unclassified"
    return "not_found_in_checkout"

