      {"name":"MOTIP-2","year":2025,"venue":"CVPR","repo":"https://github.com/GISer-WB/MOTIP-2","paper":"https://arxiv.org/abs/2403.16848","local_repo":"third_party/research_refs_phase4n/MOTIP-2","commit":head("third_party/research_refs_phase4n/MOTIP-2"),"license":license_name("third_party/research_refs_phase4n/MOTIP-2"),"inputs":"detector embeddings and historical trajectories","outputs":"ID prediction/association","online_causal":True,"persistent_query":True,"cross_video_correspondence":False,"uses_text_category_id":"trajectory IDs are in-context prompts in original task; forbidden as semantic features","reusable":"history-conditioned association formulation and trajectory memory","reject":"numeric identity prompts must be removed; no unknown-category correspondence","official_command":"bash scripts/train.sh (repo-specific configs)"},
      {"name":"COVTrack","year":2025,"venue":"ICCV","repo":"https://github.com/zekunqian/COVTrack","paper":"https://openaccess.thecvf.com/content/ICCV2025/html/Qian_Continuous_Open-Vocabulary_Tracking_via_Adaptive_Multi-Cue_Fusion_ICCV_2025_paper.html","local_repo":"third_party/research_refs_phase4n/COVTrack","commit":head("third_party/research_refs_phase4n/COVTrack"),"license":license_name("third_party/research_refs_phase4n/COVTrack"),"inputs":"detector proposals, appearance/motion/semantic cues and confidence","outputs":"open-vocabulary tracks and cue-fusion scores","online_causal":True,"persistent_query":False,"cross_video_correspondence":False,"uses_text_category_id":"semantic cue/category-aware prompt exists; excluded","reusable":"confidence, momentum appearance and motion cue separation","reject":"depends on external open-vocabulary detector and semantic cue; not TrackOCD correspondence","official_command":"python run_later.py"},
      {"name":"TRACT","year":2025,"venue":"ICCV","repo":"https://github.com/Nathan-Li123/TRACT","paper":"https://openaccess.thecvf.com/content/ICCV2025/html/Li_Attention_to_Trajectory_Trajectory-Aware_Open-Vocabulary_Tracking_ICCV_2025_paper.html","local_repo":"third_party/TRACT","commit":head("third_party/TRACT"),"license":license_name("third_party/TRACT/masa"),"inputs":"external detector/MASA tracks and trajectory crops; TraCLIP uses CLIP text for classification","outputs":"trajectory-aware association/classification","online_causal":True,"persistent_query":False,"cross_video_correspondence":False,"uses_text_category_id":"TraCLIP explicitly uses CLIP text/category names; excluded","reusable":"trajectory feature aggregation and consistency ideas","reject":"external proposals and text branch; no semantic StateMemory/Commit-Defer","official_command":"see README.md"},
